const root=$('#studio');
const ai={open:false,busy:false,error:'',messages:[],result:null,goal:'',material:'',attachment:null,fileName:'',status:null,question:'',tool:null};
let activeFilter='All tools', demoPart=0, showDraft=false, quizAnswer=null;
function header(){return `<header class="site-header"><a class="wordmark" href="#home" aria-label="PINA Studio home"><span class="brand-mark" aria-hidden="true"><i></i><i></i><i></i><i></i></span>PINA<small>STUDIO</small></a><nav class="main-nav" aria-label="Main navigation"><button class="nav-button" data-menu aria-expanded="false" aria-controls="tool-menu">Make Things Visible ${icon('chevron')}</button><a class="nav-optional" href="#stories">Netflix stories</a><a href="#notebook">My notebook</a><span class="nav-spacer"></span><button class="header-ask" data-ask>${icon('spark')} Ask Pip <span class="key-hint">⌘ K</span></button></nav><a class="pill small dark" href="#tool/1/project">Open a workspace ${icon('arrow')}</a><div class="mega-menu" id="tool-menu" hidden>${STUDIO_GROUPS.map(([title,ids])=>`<section class="mega-group"><h3>${title}</h3>${ids.map(id=>`<a href="#tool/${id}/idea">${toolName(id)}</a>`).join('')}</section>`).join('')}<div class="mega-foot"><a href="#tools">Explore every tool →</a><a href="#notebook">Continue your work →</a><a href="/">Original PINA toolkit ↗</a></div></div></header>`}
const footer=()=>`<footer class="footer"><a href="#home" class="wordmark">PINA</a><span>A space to interpret, decide and make meaning.</span><div class="footer-links"><a href="/">Original toolkit ↗</a><button data-ask>Meet Pip ${icon('spark')}</button></div></footer>`;
function shell(body){root.innerHTML=header()+body+footer();bindContent();}
function toolCard(id){return `<a href="#tool/${id}/idea" class="tool-card"><div class="tool-image">${studioMap(id,{mini:true})}</div><div class="tool-card-head"><h3>${toolName(id)}</h3>${icon('arrow')}</div><p>${esc(PIP_TOOLS[id][1])}</p><div class="tool-method-tags" role="group" aria-label="Methods covered by ${esc(toolName(id))}: ${esc(STUDIO_METHOD_TAGS[id].join(', '))}">${STUDIO_METHOD_TAGS[id].map(tag=>`<span class="tool-method-tag">${esc(tag)}</span>`).join('')}</div></a>`}
function gallery(){const ids=activeFilter==='All tools'?ALL_IDS:STUDIO_GROUPS.find(g=>g[0]===activeFilter)?.[1]||ALL_IDS;return ids.map(toolCard).join('')}
function home(){shell(`<main id="main"><section class="hero"><p class="eyebrow">THE PINA INTERPRETATION TOOLKIT</p><h1>Make sense of it.<br><span>Make your next move.</span></h1><p class="hero-desc">A brief. A message. A decision that needs a little clarity.<br>Bring it to Pip, or find the right tool yourself.</p><form class="composer" data-hero-form><label for="hero-prompt" class="sr-only">What are you working through?</label><textarea id="hero-prompt" placeholder="Tell Pip what you’re working on, or paste your brief…" maxlength="36000"></textarea><div class="composer-bottom"><button type="button" class="pill small" data-home-attach>${icon('plus')} Attach a brief</button><span class="attachment-name" data-home-file></span><button class="round dark right" aria-label="Send to Pip">${icon('arrow')}</button></div></form><div class="starter-list"><button data-starter="Help me understand the problem behind this brief.">Understand a brief ${icon('arrow')}</button><button data-starter="Help me check how this message might be understood.">Check a message ${icon('arrow')}</button><button data-starter="Help me build a convincing recommendation.">Make a recommendation ${icon('arrow')}</button></div><div class="hero-foot">${pipArt()}Pip is your thinking partner. Your judgment stays in the loop.</div></section><div class="rail" aria-label="PINA tool categories"><div class="rail-track">${[...STUDIO_GROUPS,...STUDIO_GROUPS,...STUDIO_GROUPS,...STUDIO_GROUPS].map(([n])=>`<span>${n}</span>`).join('')}</div></div><section class="section container" id="tools"><div class="section-header"><h2>Tools that make<br>thinking visible.</h2><p>Start where the work gets stuck. Each tool connects an idea, your project and a real-world example.</p></div><div class="filters" aria-label="Filter tools">${['All tools',...STUDIO_GROUPS.map(g=>g[0])].map(n=>`<button class="filter" data-filter="${esc(n)}" aria-pressed="${activeFilter===n}">${n}</button>`).join('')}</div><div class="tool-grid" id="tool-grid">${gallery()}</div></section><section class="section" style="background:var(--studio-feature)"><div class="container split-feature"><div class="split-copy"><p class="eyebrow">A LITTLE STRUCTURE. ROOM TO THINK.</p><h2>The idea becomes<br>something you can use.</h2><p>Choose how you want to begin. You can learn the framework, bring your own project or see the same questions applied to Netflix.</p><div class="feature-steps">${[['Explore the idea','Open one part at a time. See what it means, why it matters and where it sits on the map.'],['Work on your project','Answer focused questions or ask Pip for a first pass. Your map changes as your thinking becomes clearer.'],['See it in context','Follow a Netflix example to see how the tool reveals a different reading of the same situation.']].map(([n,d],i)=>`<div class="feature-step ${i===0?'open':''}"><button data-demo="${i}" aria-expanded="${i===0}"><span class="num">0${i+1}</span>${n}${icon('plus')}</button><div class="feature-body"><div><p>${d}</p></div></div></div>`).join('')}</div><a class="text-link" href="#tool/1/idea">Try Brief X-Ray ${icon('arrow')}</a></div><div class="feature-visual"><div class="visual-label"><span data-demo-label>BRIEF X-RAY · THE IDEA</span><span>01 / 03</span></div><div id="demo-map">${studioMap(1,{part:0,mini:true})}</div></div></div></section><section class="stories" id="stories"><div class="container"><p class="eyebrow">SAME COMPANY. DIFFERENT READINGS.</p><div class="section-header"><h2>Seen through<br>the Netflix lens.</h2><p>Explore the gap between what a message intends and what people might hear.</p></div><div class="stories-grid">${[['sharing','A shared password. A changed expectation.','BRIEFS & PEOPLE',1],['artwork','One show. More than one interpretation.','ANALYSIS & DECISIONS',2],['ads','When “right now” sounds like “forever.”','MESSAGES & PERSUASION',0]].map(([art,title,category,id])=>`<a class="story-card" href="#tool/${id}/case"><div class="story-image">${storyArt(art)}</div><div><p class="story-category">${category}</p><h3>${title}</h3><span class="text-link">Explore the story ${icon('arrow')}</span></div></a>`).join('')}</div><p class="small-print">PINA case analyses use Netflix examples as a lens for learning. Possible audience readings are interpretations, not statements from Netflix.</p></div></section></main>`);if(['#tools','#stories'].includes(location.hash))requestAnimationFrame(()=>$(location.hash)?.scrollIntoView());}
function toolHead(id,mode){return `<section class="page-head"><div class="container"><nav class="breadcrumb" aria-label="Breadcrumb"><a href="#tools">All tools</a><span>/</span><span>${toolGroup(id)[0]}</span></nav><div class="page-title"><div><h1>${toolName(id)}</h1><p>${esc(toolDesc(id))}</p></div></div><nav class="tool-modes" aria-label="Use this tool"><a href="#tool/${id}/idea" ${mode==='idea'?'aria-current="page"':''}>${icon('book')} Explore the idea</a><a href="#tool/${id}/project" ${mode==='project'?'aria-current="page"':''}>${icon('pen')} Work on my project</a><a href="#tool/${id}/case" ${mode==='case'?'aria-current="page"':''}>${icon('chat')} ${id===6?'Studio':'Netflix'} example</a><button class="tool-assistant-link" data-ask>${icon('spark')} Ask Pip</button></nav></div></section>`}
function mapForMode(id,mode){if(mode!=='case')return studioMap(id,{live:mode==='project',part:mode==='idea'?current.part:-1});const old=work;work={...work,...exampleForCase(id)};const caseParts={0:[0,2,4],1:[0,3,4],2:[0,3,4],3:[1,3,4],4:[0,1,2],5:[0,2,4],6:[0,2,4],7:[0,-1,2]};const svg=studioMap(id,{live:true,part:caseParts[id]?.[current.part]??-1});work=old;return svg;}
function preview(id,mode){return `<aside class="preview" aria-label="Live method preview"><div class="preview-bar"><span>${toolName(id)}</span><span class="live-dot">${mode==='project'?'Live preview':mode==='case'?'Example map':'Interactive map'}</span></div><div class="preview-map" id="live-map">${mapForMode(id,mode)}</div><div class="preview-caption" id="map-caption">${mapCaption(id,mode)}</div><div class="preview-footer"><span>${mode==='project'?'Your inputs shape this map.':'A framework for thinking, not a score to pass.'}</span>${mode==='project'?'<button data-review>Review draft ↗</button>':'<span>PINA / STUDIO</span>'}</div></aside>`}
function mapCaption(id,mode){if(mode==='project'){if(id===7)return 'Power is the ability to shape a decision. Interest is how much the outcome matters. Add names and ratings to place people on the matrix.';if(id===3)return 'F1, F2 and F3 move to the rung you choose. The rung describes how the finding was gathered.';if(id===8)return 'Adjust each lever with the large sliders in your inputs. An honest cue still needs room for someone to decline.';if(id===13)return 'Allocate exactly 100 points to each side. The weights are estimates to discuss, not measurements.';return 'Your map updates as you type. The full answers stay in your editable draft.'}if(mode==='case')return 'An illustrative reading of the case. Compare the reasoning with your own situation.';const s=lessons(id)[current.part];return s?`<b>${esc(s[0])}.</b> ${esc(s[2]||'')}`:'Select a part to explore the map.'}
function toolPage(id,mode){if(ai.tool!==id){ai.messages=[];ai.result=null;ai.error='';}current.id=id;current.mode=mode;current.part=0;current.group=0;current.tab='inputs';showDraft=false;quizAnswer=null;ai.tool=id;shell(`<main id="main">${toolHead(id,mode)}<div class="container workspace"><section class="workspace-left" id="workspace-left">${mode==='idea'?ideaContent(id):mode==='project'?projectContent(id):caseContent(id)}</section>${preview(id,mode)}</div></main>`);}
function ideaContent(id){const ls=lessons(id);return `<p class="eyebrow">WHEN WOULD I USE THIS?</p><p class="learn-intro">${esc(toolWhen(id))}</p><div class="learn-steps">${ls.map(([title,meaning,action,why],i)=>`<article class="learn-step ${i===current.part?'open':''}"><button class="learn-toggle" data-lesson="${i}" aria-expanded="${i===current.part}" aria-controls="lesson-${i}"><span class="step-no">0${i+1}</span>${esc(title)}${icon('chevron')}</button><div class="learn-body" aria-hidden="${i!==current.part}" id="lesson-${i}"><div><p class="meaning">${esc(meaning)}</p><div class="learn-action"><b>Try it</b>${esc(action)}</div><div class="pip-note">${pipArt()}<p><b>Pip · Why this matters</b>${esc(why)}</p></div></div></div></article>`).join('')}</div><div class="learn-nav"><button class="text-link" data-prev-part ${current.part===0?'disabled':''}>${icon('back')} Previous</button><button class="pill small dark" data-next-part>Next part ${icon('arrow')}</button></div><div id="quiz-area"></div>${id===11?trapGlossary():''}${id===8?leverGlossary():''}<details class="research"><summary>The research behind this tool</summary><p>${esc(id<7?SOURCE_CONTENT[id]?.research:ANYTIME_SOURCE[id]?.research)}</p></details>`}
function selectPart(n){const max=current.mode==='case'?caseSteps(current.id).length-1:lessons(current.id).length-1;current.part=Math.max(0,Math.min(n,max));$$('.learn-step').forEach((el,i)=>{el.classList.toggle('open',i===current.part);el.querySelector('button').setAttribute('aria-expanded',String(i===current.part));el.querySelector('.learn-body')?.setAttribute('aria-hidden',String(i!==current.part))});$('#live-map').innerHTML=mapForMode(current.id,current.mode);$('#map-caption').innerHTML=mapCaption(current.id,current.mode);$('[data-prev-part]')?.toggleAttribute('disabled',current.part===0);const next=$('[data-next-part]');if(next){next.innerHTML=(current.part===max?'Check understanding':'Next part')+' '+icon('arrow');next.dataset.finished=String(current.part===max)}}
function trapGlossary(){return `<div class="reference-glossary"><p class="eyebrow">NAME THE TRAP</p>${LOGIC_DECK.map(([name,def,example,,fix])=>`<details name="traps"><summary>${esc(name)}</summary><div><p>${esc(def)}</p><p><b>For example</b><br>${esc(example)}</p><p><b>A better move</b><br>${esc(fix)}</p></div></details>`).join('')}</div>`;}
function leverGlossary(){return `<div class="reference-glossary"><p class="eyebrow">THE SEVEN LEVERS</p>${LEVERS.map(([name,def])=>`<details name="levers"><summary>${esc(name)}</summary><div><p>${esc(def)}</p></div></details>`).join('')}</div>`;}
function quizFor(id){if(id>=7&&ANYTIME[id]?.quiz)return ANYTIME[id].quiz;const q={1:['A brief asks you to build a platform. What should you establish first?',['Which software to use','The need behind the requested solution','The visual style'],1,'Separate the requested deliverable from the need it is meant to meet. The reframe comes after reviewing the assumptions and people affected.'],2:['What does a warrant explain?',['Why the evidence supports the claim','How confident the presenter sounds','Which frame the team likes'],0,'The warrant is the reasoning bridge. Evidence alone can support more than one interpretation.'],3:['A small survey shows what people say they will do. Which rung fits?',['Many said it','We saw it','We tested it'],0,'Reported intentions belong on the “many said it” rung. Check the sample, study quality and context as well.']};return q[id]||['What is the most useful result of this tool?',['A final answer that cannot change','A visible line of reasoning you can examine','A more complicated presentation'],1,'The tool makes the reasoning visible, so you can question it and decide what to do next.'];}
function quizMarkupStudio(id){const [q,choices]=quizFor(id);return `<section class="quiz"><p class="eyebrow">A QUICK CHECK</p><h2>Check your understanding.</h2><p>${esc(q)}</p><div class="quiz-options">${choices.map((s,i)=>`<button data-quiz="${i}" aria-pressed="false">${esc(s)}</button>`).join('')}</div><div class="quiz-feedback" id="quiz-feedback" aria-live="polite"></div><a class="pill small dark" href="#tool/${id}/project">Try it on my project ${icon('arrow')}</a></section>`}
function projectContent(id){return `<div class="workspace-tabs" role="tablist" aria-label="Project input mode"><button role="tab" aria-selected="${current.tab==='inputs'}" data-tab="inputs" class="${current.tab==='inputs'?'active':''}">${icon('pen')} Your inputs</button><button role="tab" aria-selected="${current.tab==='chat'}" data-tab="chat" class="${current.tab==='chat'?'active':''}">${icon('spark')} Ask Pip</button><button class="restart" data-restart>Restart project</button></div><div id="project-panel" role="tabpanel">${current.tab==='chat'?inlineChat():showDraft?draftContent(id):inputContent(id)}</div>`}
function inputContent(id){const groups=INPUT_GROUPS[id],[title,keys]=groups[current.group];return `<button class="example-button" data-example>${icon('plus')} Fill empty fields with an example</button><div class="group-progress" aria-label="Project sections">${groups.map(([n],i)=>`<button aria-label="Section ${i+1}: ${esc(n)}" title="${esc(n)}" data-group="${i}" class="${i===current.group?'active':''}" ${i===current.group?'aria-current="step"':''}></button>`).join('')}</div><div class="group-heading"><h2>${esc(title)}</h2><p>${esc(current.group===0?toolWhen(id):id===7&&current.group===1?'Choose the people who can shape this change or will feel its effects. Place each person on both axes.':'Keep the answers in your own words. You can revisit them whenever your thinking changes.')}</p></div><form data-input-form>${keys.map((key,i)=>`${id===7&&/^n[1-4]$/.test(key)?`<h3 class="stakeholder-divider">Person or group ${key[1]}</h3>`:''}${fieldMarkup(id,key)}`).join('')}<div class="group-controls"><span class="step-count">${current.group+1} / ${groups.length}</span><div class="control-right">${current.group?`<button type="button" class="pill small" data-group="${current.group-1}">Go back</button>`:''}<button class="pill small dark">${current.group===groups.length-1?'Review draft':'Keep going'} ${icon('arrow')}</button></div></div></form><div class="pip-note">${pipArt()}<p><b>Pip · Your thinking stays editable</b>${esc(id===1?'The map gathers what you learn. Read it together before deciding what the real problem may be.':toolOutput(id))}</p></div>`}
function fieldMarkup(id,key){const spec=fieldSpec(id,key),label=Array.isArray(spec)?spec[0]:spec,val=value(id,key),fid='field-'+id+'-'+key;let hint=FIELD_HELP[key]||'';if(id===3&&/^r\d$/.test(key))hint='1: Someone said it · 2: Many said it · 3: We saw it · 4: We tested it';if(id===9&&key==='ours')hint='The most you pay if buying, or the least you accept if selling.';if(id===9&&key==='theirs')hint='Use a documented limit or explicitly label this as an estimate.';if(id===7&&/^[pi]\d$/.test(key))hint=key[0]==='p'?'Can they approve, block or shape this decision?':'How much does this outcome matter to them?';let input;
if((id===3&&/^l\d$/.test(key))||(id===13&&/^f\d$/.test(key))||(id===4&&/^c\d$/.test(key))||(id===8&&/^ethics\d$/.test(key)))return `<label class="checkbox-field" for="${fid}"><input id="${fid}" type="checkbox" data-field="${key}" ${val==='true'?'checked':''}><span>${esc(label)}</span></label>`;
if((id===6&&/^a\d$/.test(key))||(id===8&&/^level\d$/.test(key))||(id===10&&/^corner\d$/.test(key))){const n=val||1;input=`<div class="range-row"><input id="${fid}" data-field="${key}" type="range" min="1" max="5" step="1" value="${n}"><output class="range-value" for="${fid}">${n} / 5</output></div>`;hint=hint||'1 is low. 5 is high. Your rating is a judgment to discuss.';}
else if(id===13&&/^[ut][0-2]$/.test(key)){input=`<input id="${fid}" data-field="${key}" type="number" min="0" max="100" step="1" value="${esc(val)}" placeholder="0">`;hint='Allocate 100 points across ethics, emotion and economics for this side.';}
else if(Array.isArray(spec)&&spec[1]!=='#number'){const display=(s)=>id===7?(s==='H'?'High':'Low'):id===9&&/^(us|them)\d$/.test(key)?({1:'Low',2:'Medium',3:'High'}[s]):id===8&&key==='lead'?LEVERS[Number(s)]?.[0]:id===3&&/^r\d$/.test(key)?['','Someone said it','Many said it','We saw it','We tested it'][s]:s;input=`<select id="${fid}" data-field="${key}"><option value="">Choose…</option>${spec.slice(1).map(s=>`<option value="${esc(s)}" ${val===String(s)?'selected':''}>${esc(display(s))}</option>`).join('')}</select>`;}
else if(Array.isArray(spec)&&spec[1]==='#number')input=`<input id="${fid}" data-field="${key}" type="number" step="any" value="${esc(val)}" placeholder="Your limit">`;
else if(key==='who'||key==='audience'||key==='unit'||/^n\d$/.test(key)||key==='us'||key==='them')input=`<input id="${fid}" data-field="${key}" value="${esc(val)}" maxlength="1800" placeholder="Your words…">`;
else input=`<textarea id="${fid}" data-field="${key}" rows="${key==='brief'?5:3}" maxlength="6000" placeholder="Your words…">${esc(val)}</textarea>`;
return `<div class="field"><label class="field-title" for="${fid}">${esc(label)}</label>${hint?`<p class="field-hint" id="${fid}-hint">${esc(hint)}</p>`:''}${hint?input.replace('data-field=',`aria-describedby="${fid}-hint" data-field=`):input}</div>`;}
function draftStatement(id){const v=k=>value(id,k);if(id===1)return v('reframe')?`The problem may be ${v('reframe')}.`:'';if(id===3)return v('act')?`We recommend ${v('act')}${v('gain')?' so that '+v('gain'):''}.`:'';if(id===2)return v('see')?`If we see the problem as ${v('see')}${v('then')?', then '+v('then'):''}.`:'';if(id===12)return v('beat3');if(id===7)return v('lead');if(id===6)return v('out')?`You are paying for ${v('out')}.`:'';return '';}
function draftContent(id){const sentence=draftStatement(id);return `<article class="draft"><p class="eyebrow">YOUR WORKING DOCUMENT</p><h2>Put the thinking together.</h2>${sentence?`<p class="output-statement">${esc(sentence)}</p>`:''}<pre>${esc(draftText(id))}</pre><div class="draft-actions"><button class="pill small dark" data-copy>Copy my draft ${icon('book')}</button><button class="pill small" data-download>Download text ${icon('download')}</button></div><button class="text-link" data-revisit>${icon('back')} Revisit my answers</button></article>`}
const CASE_CONTENT={
1:[['The visible request','The request was to stop password sharing. That is the named solution. The iceberg asks what problem that solution is meant to solve.'],['Below the waterline','The analysis asks whether people would pay, what families might lose and what else could support the same interest: revenue for new shows.'],['A different problem to solve','“Love is sharing a password” could be heard as permission to share. The reframe is how to turn sharing into a paid offer without making a familiar family habit feel like a betrayal.']],
7:[['One proposal, several audiences','A regulator and a creator may hear the same Netflix proposal differently. Power and interest help you decide whom to involve and how.'],['Place the people on the matrix','The example places decision makers with high power, and affected creators or members according to their stake. These placements are hypotheses to check, not fixed facts.'],['Plan a different conversation','A regulator may want a clear account of control and review. A creator may ask who decides what gets made. Address that concern directly instead of repeating the same pitch to everyone.']],
14:[['Choose one member','Start with a member who shared an account with family. That is the person whose perspective we are trying to understand.'],['Feel, care, say and do','They might feel a familiar habit is being criticized. They may care about staying connected and being treated fairly. Their actual words and actions help you check that reading.'],['Understand what the change means','Through these lenses, you can distinguish a hypothesis about their feelings from what you have observed, and choose what to ask or explain next.']],
2:[['The grounds','The artwork example begins with the observation that a single image helps people decide what to watch.'],['An explanation and a rival','One frame is helping people find a show quickly. Another is that personalization can feel like targeting when people do not understand it.'],['What would change your mind?','A test asks whether people still find a good choice when personalization is explained, and whether the image matches the story they actually watch.']],
0:[['What Netflix meant','A statement about having no current advertising plans can sound clear in the moment.'],['What a member might hear','An emphatic statement can also be heard as a permanent promise. That is the gap between intended and received meaning.'],['Close the gap','The Reading Check asks what was meant, what people could reasonably hear and how to acknowledge a changed position clearly.']],
3:[['Different kinds of support','The case compares survey intentions with observed sign-ups and country pilots. Each supports a different kind of claim.'],['What the ladder reveals','Saying you might cancel and actually cancelling are different findings. Place each on its rung, then inspect the source and study quality.'],['A bounded recommendation','Commercial uptake alone does not settle the trust question. Recommend an action while naming what you still need to learn about member reactions.']],
4:[['The purpose','Personalized artwork aims to help each viewer find a show they will enjoy.'],['Follow it into the image','If an image suggests a minor character is the lead, it can create an expectation the show does not meet.'],['Repair the break','Compare what the thumbnail is intended to communicate with a viewer’s actual reading. Fix the image or explanation where that thread breaks.']],
5:[['Make the decision visible','Use a change such as paid sharing to ask what was decided and why.'],['Keep the rejected options','A review record should include alternatives, the reasons for rejecting them and what evidence was missing.'],['Leave a useful handover','Record the unresolved questions about expectations and trust so the next team can continue the reasoning.']],
6:[['A client questions the value','This is a studio scenario: faster production leaves a client asking what they are paying for.'],['Show the outcome','A tested frame, an avoided rework round or a decision enabled can make the value of the thinking tangible.'],['Make it testable','Offer a small trial and agree how the client will see the result. This is an application of the method, not a Netflix claim.']]};
function caseSteps(id){return CASE_CONTENT[id]||[['The situation',ANYTIME[id]?.caseReading?.[0]||'Consider the message and the people affected by it.'],['What the tool reveals',ANYTIME[id]?.caseReading?.[1]||'The method makes the reasoning and possible audience interpretations visible.'],['A next move',ANYTIME[id]?.caseReading?.[2]||'Use the map to decide what to ask, test or change before committing.']];}
function practiceExample(id){const data=projectExample(id);if(id===1)data.s1_brief='We need to reduce unpaid account sharing and increase subscriptions. Develop an approach to paid sharing that funds new shows while keeping members engaged.';return data;}
function exampleForCase(id){const data=practiceExample(id);if(id===7)return {s7_n1:'Regulator',s7_p1:'H',s7_i1:'H',s7_n2:'Studio creator',s7_p2:'L',s7_i2:'H',s7_n3:'Decision sponsor',s7_p3:'H',s7_i3:'H',s7_n4:'Adjacent viewer',s7_p4:'L',s7_i4:'L'};if(id===14)return {...data,s14_who:'A member sharing with family'};return data;}
function caseContent(id){return `<p class="eyebrow">${id===6?'A STUDIO APPLICATION':'THE NETFLIX LENS'}</p><p class="learn-intro">${id===6?'Apply the same questions to a client conversation about the value of design.':'See how the same questions can uncover a different reading of a familiar message or decision.'}</p><div class="learn-steps">${caseSteps(id).map(([title,text],i)=>`<article class="learn-step ${i===current.part?'open':''}"><button class="learn-toggle" data-lesson="${i}" aria-expanded="${i===current.part}" aria-controls="case-part-${i}"><span class="step-no">0${i+1}</span>${esc(title)}${icon('chevron')}</button><div class="learn-body" aria-hidden="${i!==current.part}" id="case-part-${i}"><div><p class="meaning">${esc(text)}</p><div class="pip-note">${pipArt()}<p><b>Pip · Bring it back to your work</b>Which part of this situation resembles the decision or message in front of you?</p></div></div></div></article>`).join('')}</div><div class="learn-nav"><button class="text-link" data-prev-part disabled>${icon('back')} Previous</button><button class="pill small dark" data-next-part>Next part ${icon('arrow')}</button></div><div id="quiz-area"></div><details class="research"><summary>The research behind it</summary><p>${esc(id<7?SOURCE_CONTENT[id]?.research:ANYTIME_SOURCE[id]?.research)}</p></details><p class="case-note">A learning application from the PINA case notes. Audience reactions and stakeholder placements are interpretations to investigate. This does not claim Netflix used the PINA toolkit internally.</p>`}
function notebook(){const used=ALL_IDS.filter(id=>Object.keys(work).some(k=>k.startsWith('s'+id+'_')&&String(work[k]).trim()&&work[k]!==false));current.id=null;ai.tool=null;shell(`<main id="main" class="container notebook-page"><p class="eyebrow">YOUR THINKING, IN ONE PLACE</p><h1>My notebook.</h1><p>Return to a tool, revise your answers and keep the reasoning moving.</p>${used.length?`<div class="notebook-list">${used.map(id=>`<article class="notebook-item"><div><h2>${toolName(id)}</h2><p>${toolGroup(id)[0]}</p></div><p>${esc(draftStatement(id)||PIP_TOOLS[id][1])}</p><a class="pill small" href="#tool/${id}/project">Continue ${icon('arrow')}</a></article>`).join('')}</div>`:`<div class="empty-notebook">Your first working map will appear here once you start filling in a tool. Existing notes from the original toolkit also appear in this Studio view.<br><a class="pill small dark" href="#tools">Find a tool ${icon('arrow')}</a></div>`}</main>`);}
function refreshPreview(){if(current.id===null)return;$('#live-map').innerHTML=mapForMode(current.id,current.mode);$('#map-caption').innerHTML=mapCaption(current.id,current.mode);}
function route(){const hash=location.hash||'#home',m=hash.match(/^#tool\/(\d+)\/(idea|project|case)$/);if(m&&PIP_TOOLS[+m[1]]){toolPage(+m[1],m[2]);window.scrollTo({top:0,behavior:'instant'})}else if(hash==='#notebook'){notebook();window.scrollTo({top:0,behavior:'instant'})}else {current.id=null;ai.tool=null;home();if(!['#tools','#stories'].includes(hash))window.scrollTo({top:0,behavior:'instant'})}if(ai.open)renderAssistant();}
async function pipApi(action,body){let response,data;try{response=await fetch('/api/pip/'+action,body===undefined?{cache:'no-store'}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});data=await response.json()}catch{throw Error('Pip could not connect. Your manual tools are still available.')}if(!response.ok)throw Object.assign(Error((data.error||'Pip could not finish that request.').replace(/\bPip\b/g,'Pip')),{code:data.code});return data;}
async function checkAI(){try{ai.status=await pipApi('status');return ai.status}catch(err){ai.status=null;return null}}
function chatContents(){return `${!ai.messages.length?`<div class="chat-welcome">Hi, I’m Pip.<br>What are we working through?</div><p class="chat-small">I’m PINA’s thinking partner. I can help you choose a tool, make sense of your material or draft answers for you to review.</p>${!ai.tool&&ai.tool!==0?`<div class="goal-list" aria-label="What do you want to do?">${PIP_GOALS.map(([key,label])=>`<button data-goal="${key}" aria-pressed="${ai.goal===key}">${label}</button>`).join('')}</div>`:''}`:''}${ai.messages.map(m=>`<div class="chat-message ${m.role}"><span class="chat-who">${m.role==='user'?'You':'Pip'}</span>${esc(m.text.replace(/\bPip\b/g,'Pip'))}</div>`).join('')}${ai.busy?'<p class="loading" role="status">Pip is working through your material…</p>':''}${ai.error?`<p class="error" role="alert">${esc(ai.error)}</p>${/vault|key|settings|locked|unavailable/i.test(ai.error)?'<button class="settings-link" data-settings>'+icon('gear')+' Open AI settings</button>':''}`:''}${ai.result?.tools?.length?ai.result.tools.filter(t=>PIP_TOOLS[t.id]).map(t=>`<a href="#tool/${t.id}/project" class="ai-recommendation" data-follow-tool><b>${toolName(t.id)} ↗</b><p>${esc(t.reason)}</p>${t.quote?`<p>“${esc(t.quote)}”</p>`:''}</a>`).join(''):''}${ai.result?.suggestions?.length?ai.result.suggestions.map((s,i)=>({s,i})).filter(({s})=>Object.hasOwn(pipSpecs(ai.tool),s.field)).map(({s,i})=>`<article class="suggestion"><small>${s.kind==='stated'?'From your material':'An inference to review'}</small><h3>${esc(Array.isArray(fieldSpec(ai.tool,s.field))?fieldSpec(ai.tool,s.field)[0]:fieldSpec(ai.tool,s.field))}</h3><p>${esc(s.value)}</p>${s.quote?`<blockquote>“${esc(s.quote)}”</blockquote>`:''}<button class="pill small" data-apply="${i}">${value(ai.tool,s.field)?'Replace this answer':'Use this suggestion'} ${icon('check')}</button></article>`).join(''):''}${ai.result?.question?`<p class="chat-small"><b>A question to consider</b><br>${esc(ai.result.question)}</p>`:''}${ai.result?.next?.length?`<div class="chat-small"><b>Possible next moves</b><ol>${ai.result.next.map(s=>`<li>${esc(s)}</li>`).join('')}</ol></div>`:''}`}
function chatComposer(){return `<form class="chat-compose" data-chat-form><label class="sr-only" for="pip-question">Your question for Pip</label><textarea id="pip-question" placeholder="Ask a question or add your material…" maxlength="36000">${esc(ai.question)}</textarea><div class="chat-compose-bottom"><button type="button" class="round" data-attach aria-label="Attach a PDF, image or text file">${icon('plus')}</button><span class="attachment-name">${esc(ai.fileName)}</span>${ai.fileName?'<button type="button" class="text-link" data-remove-file aria-label="Remove attachment">×</button>':''}<button class="pill small dark right" ${ai.busy?'disabled':''}>Ask Pip ${icon('arrow')}</button></div><input type="file" data-ai-file accept=".pdf,.png,.jpg,.jpeg,.webp,.txt,.md" hidden></form>`}
function inlineChat(){return `<div class="inline-chat"><p class="chat-small">Pip can use your current answers as context. Review each suggestion before adding it to your map.</p><div class="assistant-scroll">${chatContents()}</div>${chatComposer()}<button class="settings-link" data-settings>${icon('gear')} AI settings</button></div>`}
function renderAssistant(){const layer=$('#assistant');layer.innerHTML=ai.open?`<aside class="assistant-panel" aria-label="Ask Pip"><header class="assistant-head">${pipArt()}<div><h2>Ask Pip</h2><p>${ai.tool!==null?toolName(ai.tool):'YOUR INTERPRETATION GUIDE'}</p></div><div class="actions"><button class="round" aria-label="AI settings" data-settings>${icon('gear')}</button><button class="round" aria-label="Close Ask Pip" data-close-ai>${icon('close')}</button></div></header><div class="assistant-scroll" id="chat-scroll">${chatContents()}</div>${chatComposer()}</aside>`:`<button class="assistant-launcher" data-ask aria-label="Ask Pip">${pipArt()} Ask Pip ${icon('spark')}</button>`;}
function renderChat(){if(ai.open)renderAssistant();else if(current.id!==null&&current.mode==='project'&&current.tab==='chat')$('#project-panel').innerHTML=inlineChat();}
function openAI(){if(current.mode==='project'&&current.id!==null){ai.open=false;current.tab='chat';showDraft=false;$('#workspace-left').innerHTML=projectContent(current.id);renderAssistant();$('#pip-question')?.focus({preventScroll:true});}else {ai.open=true;renderAssistant();$('#pip-question')?.focus({preventScroll:true});}checkAI();}
async function askPip(question){if(ai.busy)return;const q=String(question||'').trim();if(!q&&!ai.attachment&&!ai.material){notice('Add a question, brief or attachment first.');return}ai.question='';ai.error='';ai.busy=true;ai.result=null;ai.messages.push({role:'user',text:q||'Please review the attached material.'});renderChat();try{const fields=ai.tool===null?{}:Object.fromEntries(Object.keys(pipSpecs(ai.tool)).map(k=>[k,value(ai.tool,k)]).filter(([,v])=>v));let question=q;if(q.length>2500){ai.material=(ai.material+'\n'+q).trim().slice(0,36000);question='Help me understand this material and suggest the next useful step.';}const previous=ai.messages.slice(-5,-1).map(m=>`${m.role}: ${m.text}`).join('\n').slice(-1000);const result=await pipApi('assist',{tool:ai.tool,goal:ai.goal,material:ai.material,question:(question+(previous?'\n\nEarlier context: '+previous:'')).slice(0,2600),fields,attachment:ai.attachment});ai.result=result;ai.messages.push({role:'assistant',text:result.reply||'Here are some suggestions to review.'});}catch(err){ai.error=err.message;}finally{ai.busy=false;renderChat();}}
async function readAttachment(file){if(!file)return;if(file.size>5*1024*1024){notice('Use a file up to 5 MB.');return}if(/\.(txt|md)$/i.test(file.name)){ai.material=(await file.text()).slice(0,36000);ai.attachment=null;}else {const mime=file.type||(/\.pdf$/i.test(file.name)?'application/pdf':'');if(!['application/pdf','image/png','image/jpeg','image/webp'].includes(mime)){notice('Use a PDF, PNG, JPG, WebP, TXT or Markdown file.');return}const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result.split(',')[1]);r.onerror=reject;r.readAsDataURL(file)});ai.attachment={mime,data};ai.material='';}ai.fileName=file.name;renderChat();if($('[data-home-file]'))$('[data-home-file]').textContent=file.name;}
async function openSettings(){const d=$('#settings');d.innerHTML=`<div class="dialog-head"><h2 id="settings-title">Pip’s AI settings</h2><button class="round" data-dialog-close="settings" aria-label="Close settings">${icon('close')}</button></div><p class="dialog-copy">Checking your current setup…</p>`;if(!d.open)d.showModal();const s=await checkAI();settingsBody(s);}
function settingsBody(s,error=''){const d=$('#settings');d.innerHTML=`<div class="dialog-head"><h2 id="settings-title">Pip’s AI settings</h2><button class="round" data-dialog-close="settings" aria-label="Close settings">${icon('close')}</button></div>${error?`<p class="error">${esc(error)}</p>`:''}${!s?'<p class="dialog-copy">Pip’s service could not be reached. The manual tools remain available.</p><button class="pill small" data-settings>Check again</button>':!s.unlocked?`<p class="dialog-copy">${s.shared?'Your shared AI access is ready. Owner settings are separate.':s.created?'Your API key remains saved. Unlock your existing vault to use or change it.':'Use the same browser as your existing PINA setup. If you have not set it up here, create a passphrase to protect your API key.'}</p><form class="dialog-form" data-settings-form="${s.created?'unlock':'create'}"><div class="field"><label class="field-title" for="vault-passphrase">${s.created?'Existing':'New'} passphrase</label><input id="vault-passphrase" name="password" type="password" minlength="12" maxlength="256" autocomplete="${s.created?'current-password':'new-password'}" required></div>${!s.created?'<p class="dialog-copy">Use at least 12 characters. Your provider key is encrypted by the existing PINA backend.</p>':''}<button class="pill small dark">${s.created?'Unlock vault':'Create vault'}</button></form>`:`<p class="dialog-copy">${s.configured?`Connected provider: ${s.provider==='gemini'?'Google Gemini':'OpenAI'}. Your saved key is not shown.`:'Add your provider’s API key. It is stored by the existing encrypted PINA vault.'}</p><form class="dialog-form" data-settings-form="config"><div class="field"><label class="field-title" for="ai-provider">Provider</label><select id="ai-provider" name="provider"><option value="gemini" ${s.provider==='gemini'?'selected':''}>Google Gemini</option><option value="openai" ${s.provider==='openai'?'selected':''}>OpenAI</option></select></div><div class="field"><label class="field-title" for="ai-key">${s.configured?'Replace API key (optional)':'API key'}</label><input id="ai-key" name="key" type="password" autocomplete="off" ${s.configured?'':'required'}></div><div class="field"><label class="field-title" for="ai-model">Model ID</label><input id="ai-model" name="model" value="${esc(s.model)}" placeholder="Use provider default"></div><button class="pill small dark">Save connection</button><button class="pill small" type="button" data-test-ai>Test connection</button></form><p class="dialog-copy">This Studio uses the same AI setup as your original toolkit. Provider requests count toward that account’s quota.</p><button class="text-link" data-lock-ai>Lock owner settings</button>`}`;}
function confirmRestart(){const d=$('#confirm');d.innerHTML=`<div class="dialog-head"><h2 id="confirm-title">Restart ${toolName(current.id)}?</h2></div><p class="dialog-copy">This clears your answers for this tool. Your other tools stay in your notebook. Download your draft first if you want to keep it.</p><div class="draft-actions"><button class="pill small" data-dialog-close="confirm">Cancel</button><button class="pill small dark" data-confirm-restart>Restart project</button></div>`;d.showModal();}
function bindContent(){}
document.addEventListener('click',async e=>{const b=e.target.closest('button,a,[data-part]');if(!b)return;
if(b.matches('[data-menu]')){const menu=$('#tool-menu'),open=menu.hidden;menu.hidden=!open;b.setAttribute('aria-expanded',String(open));}
if(b.matches('.mega-menu a'))$('#tool-menu').hidden=true;
if(b.dataset.filter){activeFilter=b.dataset.filter;$$('[data-filter]').forEach(n=>n.setAttribute('aria-pressed',String(n===b)));$('#tool-grid').innerHTML=gallery();}
if(b.dataset.starter){$('#hero-prompt').value=b.dataset.starter;$('#hero-prompt').focus();}
if(b.hasAttribute('data-demo')){demoPart=+b.dataset.demo;$$('.feature-step').forEach((n,i)=>{n.classList.toggle('open',i===demoPart);n.querySelector('button').setAttribute('aria-expanded',String(i===demoPart))});$('#demo-map').innerHTML=studioMap(1,{live:demoPart!==0,part:demoPart,mini:true});$('[data-demo-label]').textContent=['BRIEF X-RAY · THE IDEA','BRIEF X-RAY · YOUR PROJECT','BRIEF X-RAY · IN CONTEXT'][demoPart];$('.visual-label>span:last-child').textContent='0'+(demoPart+1)+' / 03';}
if(b.hasAttribute('data-lesson'))selectPart(+b.dataset.lesson);
if(b.hasAttribute('data-part')&&current.mode==='idea')selectPart(Math.min(+b.dataset.part,lessons(current.id).length-1));
if(b.hasAttribute('data-prev-part'))selectPart(current.part-1);
if(b.hasAttribute('data-next-part')){const max=current.mode==='case'?caseSteps(current.id).length-1:lessons(current.id).length-1;if(current.part===max){$('#quiz-area').innerHTML=quizMarkupStudio(current.id);$('#quiz-area').scrollIntoView({block:'nearest',behavior:'smooth'});}else selectPart(current.part+1);}
if(b.hasAttribute('data-quiz')){quizAnswer=+b.dataset.quiz;const q=quizFor(current.id);$$('[data-quiz]').forEach(n=>n.setAttribute('aria-pressed',String(n===b)));$('#quiz-feedback').textContent=(quizAnswer===q[2]?'That’s it. ':'Take another look. ')+q[3];}
if(b.dataset.tab){current.tab=b.dataset.tab;showDraft=false;ai.open=false;$('#workspace-left').innerHTML=projectContent(current.id);renderAssistant();}
if(b.hasAttribute('data-group')){current.group=+b.dataset.group;showDraft=false;$('#project-panel').innerHTML=inputContent(current.id);}
if(b.hasAttribute('data-example')){const example=practiceExample(current.id);let count=0;for(const [k,v] of Object.entries(example))if(!work[k]&&k.startsWith('s'+current.id+'_')){work[k]=v;count++;}saveAnswers();$('#project-panel').innerHTML=inputContent(current.id);refreshPreview();notice(count?'Example added to empty fields. Existing answers were kept.':'Your fields already have answers.');}
if(b.hasAttribute('data-review')){current.tab='inputs';showDraft=true;$('#workspace-left').innerHTML=projectContent(current.id);}
if(b.hasAttribute('data-revisit')){showDraft=false;current.group=0;$('#project-panel').innerHTML=inputContent(current.id);}
if(b.hasAttribute('data-copy')){try{await navigator.clipboard.writeText(draftText(current.id));notice('Draft copied.');}catch{notice('Copy is unavailable here. Use Download text.');}}
if(b.hasAttribute('data-download')){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([draftText(current.id)],{type:'text/plain;charset=utf-8'}));a.download='PINA-'+toolName(current.id).replace(/[^a-z0-9]+/gi,'-')+'.txt';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
if(b.hasAttribute('data-restart'))confirmRestart();
if(b.hasAttribute('data-confirm-restart')){for(const key of Object.keys(work))if(key.startsWith('s'+current.id+'_'))delete work[key];saveAnswers();current.group=0;showDraft=false;$('#confirm').close();$('#workspace-left').innerHTML=projectContent(current.id);refreshPreview();notice('This tool is ready for a fresh project.');}
if(b.hasAttribute('data-ask'))openAI();
if(b.hasAttribute('data-close-ai')){ai.open=false;renderAssistant();}
if(b.hasAttribute('data-follow-tool')){ai.open=false;ai.result=null;renderAssistant();}
if(b.dataset.goal){ai.goal=b.dataset.goal;renderChat();}
if(b.hasAttribute('data-attach'))$('[data-ai-file]')?.click();
if(b.hasAttribute('data-home-attach')){ai.open=true;renderAssistant();$('[data-ai-file]').click();}
if(b.hasAttribute('data-remove-file')){ai.fileName='';ai.attachment=null;ai.material='';renderChat();}
if(b.hasAttribute('data-apply')){const suggestion=ai.result?.suggestions?.[+b.dataset.apply];if(suggestion&&ai.tool!==null&&Object.hasOwn(pipSpecs(ai.tool),suggestion.field)){const spec=pipSpecs(ai.tool)[suggestion.field],s=String(suggestion.value);if(Array.isArray(spec)&&spec[1]!=='#number'&&!spec.slice(1).includes(s)){notice('Review this suggested value manually in your inputs.');return}work['s'+ai.tool+'_'+suggestion.field]=s;saveAnswers();refreshPreview();notice('Suggestion added. You can edit it in Your inputs.');b.textContent='Added ✓';}}
if(b.hasAttribute('data-settings'))await openSettings();
if(b.dataset.dialogClose)$('#'+b.dataset.dialogClose).close();
if(b.hasAttribute('data-test-ai')){b.disabled=true;try{await pipApi('test',{});notice('AI connection is working.');}catch(err){settingsBody(ai.status,err.message)}finally{b.disabled=false}}
if(b.hasAttribute('data-lock-ai')){try{ai.status=await pipApi('lock',{});settingsBody(ai.status)}catch(err){settingsBody(ai.status,err.message)}}
});
document.addEventListener('input',e=>{const f=e.target;if(f.matches('[data-field]')){work['s'+current.id+'_'+f.dataset.field]=f.type==='checkbox'?f.checked:f.value;saveAnswers();if(f.type==='range')f.nextElementSibling.textContent=f.value+' / 5';refreshPreview();}if(f.id==='pip-question')ai.question=f.value;});
document.addEventListener('change',async e=>{if(e.target.matches('[data-ai-file]')){try{await readAttachment(e.target.files[0]);}catch{notice('The file could not be read. Try a different file.')}}});
document.addEventListener('submit',async e=>{const f=e.target;e.preventDefault();if(f.matches('[data-hero-form]')){const q=$('#hero-prompt').value;ai.tool=null;openAI();await askPip(q);}
if(f.matches('[data-input-form]')){if(current.group<INPUT_GROUPS[current.id].length-1){current.group++;$('#project-panel').innerHTML=inputContent(current.id)}else {showDraft=true;$('#project-panel').innerHTML=draftContent(current.id)}}
if(f.matches('[data-chat-form]'))await askPip(f.querySelector('textarea').value);
if(f.matches('[data-settings-form]')){const action=f.dataset.settingsForm,submit=f.querySelector('button');submit.disabled=true;const data=Object.fromEntries(new FormData(f));try{ai.status=await pipApi(action,data);settingsBody(ai.status);notice(action==='config'?'AI connection saved.':'Vault unlocked.');}catch(err){settingsBody(ai.status,err.message)}}
});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openAI()}if(e.key==='Escape'){if($('#tool-menu'))$('#tool-menu').hidden=true;if(ai.open){ai.open=false;renderAssistant()}}if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-part]')){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}))}});
document.addEventListener('click',e=>{if(!e.target.closest('.site-header')&&$('#tool-menu')){$('#tool-menu').hidden=true;$('[data-menu]')?.setAttribute('aria-expanded','false')}});
window.addEventListener('storage',e=>{if(e.key==='pina-fieldguide-work-v1'){work=studioRead(e.key,{});refreshPreview();}});
window.addEventListener('hashchange',route);
route();renderAssistant();
